package com.company.generated.units.u2e52a65fe1ce;

import com.ibm.dse.base.CCOperationStep;
import com.ibm.il.dse.operations.common.MapErrorByValueAlways;

public class ValidationFailedStep extends CCOperationStep {
    private final MapErrorByValueAlways delegate;

    public ValidationFailedStep() {
        this.delegate = new MapErrorByValueAlways();
        this.delegate.setErrorCategory("10");
        this.delegate.setErrorNumber("2");
    }

    @Override
    public void setContext(com.ibm.dse.base.Context context) {
        super.setContext(context);
        delegate.setContext(context);
    }

    @Override
    public int execute() throws Exception {
        return delegate.execute();
    }
}

package com.company.generated.units.u2e52a65fe1ce;

import com.ibm.dse.base.Context;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class ValidationFailedStepTest {

    @Test
    public void testExecuteSetsErrorFields() throws Exception {
        ValidationFailedStep step = new ValidationFailedStep();
        Context ctx = new Context();
        step.setContext(ctx);

        int result = step.execute();
        assertEquals(0, result);
        assertEquals("10", ctx.getValueAt("ErrorCategory"));
        assertEquals("2", ctx.getValueAt("ErrorNumber"));
        assertEquals("Validation failed: required field missing or invalid", ctx.getValueAt("ErrorDescription"));
    }
}

